## 6. Kernel端实现要点

### 6.1 执行流程（核内循环）

```cpp
__aicore__ inline void Process() {
    int64_t coreLength = AscendC::GetBlockIdx() == tiling->usedCoreNum - 1 ? this->tailLength : this->formerLength;
    int64_t tileNum = (coreLength + this->tileLength - 1) / this->tileLength;
    int64_t tailTileLength = coreLength - (tileNum - 1) * this->tileLength;

    for (int64_t i = 0; i < tileNum - 1; ++i) {
        CopyIn(i, this->tileLength);
        Compute(i, this->tileLength);
        CopyOut(i, this->tileLength);
    }
    // 处理尾块 tailTileLength
    CopyIn(tileNum - 1, tailTileLength);
    Compute(tileNum - 1, tailTileLength);
    CopyOut(tileNum - 1, tailTileLength);
}
```

### 6.2 CopyIn 函数

由于 Permute 的输入访问模式不规则（跨步/随机），无法使用向量化 DataCopy 一次性加载整个 tile。采用标量逐元素加载：

```cpp
__aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength) {
    // 对于 Permute，由于输入访问不规则，直接在 Compute 中从 GM 读取
    // 或者使用 UB 缓冲：先加载到 UB，再处理
    // 但非连续访问模式下，UB 缓冲的收益有限
}
```

### 6.3 Compute 函数

```cpp
__aicore__ inline void Compute(int64_t progress, int64_t curTileLength) {
    int64_t tileOffset = this->blockOffset + progress * this->tileLength;

    for (int64_t i = 0; i < curTileLength; ++i) {
        int64_t globalIdx = tileOffset + i;

        // 将全局线性索引转换为输出多维坐标
        int64_t out_coords[8];
        int64_t tmp = globalIdx;
        for (int d = tiling->ndim - 1; d >= 0; --d) {
            out_coords[d] = tmp % tiling->out_shape[d];
            tmp /= tiling->out_shape[d];
        }

        // 计算输入坐标: in_coords[dims[k]] = out_coords[k]
        int64_t in_coords[8];
        for (int k = 0; k < tiling->ndim; ++k) {
            in_coords[tiling->dims[k]] = out_coords[k];
        }

        // 计算输入线性索引
        int64_t srcIdx = 0;
        for (int d = 0; d < tiling->ndim; ++d) {
            srcIdx += in_coords[d] * tiling->in_strides[d];
        }

        // 复制元素
        outputGm[globalIdx] = inputGm[srcIdx];
    }
}
```

### 6.4 CopyOut 函数

```cpp
__aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength) {
    // 输出是顺序写入的，可以使用 DataCopyPad
    int64_t tileOffset = this->blockOffset + progress * this->tileLength;
    LocalTensor<T> outLocal = outQueue.DeQue<T>();
    DataCopyPad(outputGm[tileOffset], outLocal, curTileLength);
    outQueue.FreeTensor(outLocal);
}
```

