#include "kernel_operator.h"

constexpr int64_t BUFFER_NUM = 2;
constexpr int64_t MAX_DIM = 8;
constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;

struct PermuteTilingData {
    int64_t totalLength;
    int64_t usedCoreNum;
    int64_t formerNum;
    int64_t formerLength;
    int64_t tailNum;
    int64_t tailLength;
    int64_t tileLength;
    int64_t ndim;
    int64_t in_shape[MAX_DIM];
    int64_t out_shape[MAX_DIM];
    int64_t dims[MAX_DIM];
    int64_t in_strides[MAX_DIM];
};

template <typename T>
class KernelPermute {
public:
    __aicore__ inline void Init(GM_ADDR input, GM_ADDR output, GM_ADDR tiling) {
        tilingData = reinterpret_cast<__gm__ PermuteTilingData*>(tiling);

        inputGm.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(input), tilingData->totalLength);
        outputGm.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(output), tilingData->totalLength);

        int64_t dtypeSize = sizeof(T);
        pipe.InitBuffer(inQueue, BUFFER_NUM, tilingData->tileLength * dtypeSize);
        pipe.InitBuffer(outQueue, BUFFER_NUM, tilingData->tileLength * dtypeSize);
    }

    __aicore__ inline void Process() {
        int64_t blockIdx = static_cast<int64_t>(AscendC::GetBlockIdx());
        int64_t blockLength = (blockIdx == tilingData->usedCoreNum - 1) ? tilingData->tailLength : tilingData->formerLength;
        int64_t blockOffset = blockIdx * tilingData->formerLength;

        if (blockLength <= 0) {
            return;
        }

        int64_t tileNum = (blockLength + tilingData->tileLength - 1) / tilingData->tileLength;
        int64_t tailTileLength = blockLength - (tileNum - 1) * tilingData->tileLength;

        for (int64_t i = 0; i < tileNum - 1; ++i) {
            CopyIn(blockOffset + i * tilingData->tileLength, tilingData->tileLength);
            Compute(blockOffset + i * tilingData->tileLength, tilingData->tileLength);
            CopyOut(blockOffset + i * tilingData->tileLength, tilingData->tileLength);
        }

        // Process tail tile
        int64_t tailOffset = blockOffset + (tileNum - 1) * tilingData->tileLength;
        CopyIn(tailOffset, tailTileLength);
        Compute(tailOffset, tailTileLength);
        CopyOut(tailOffset, tailTileLength);
    }

private:
    __aicore__ inline void CopyIn(int64_t offset, int64_t curTileLength) {
        // For permute, input access is non-contiguous (strided).
        // We load a contiguous chunk from input GM for buffering.
        // But since we need arbitrary access, we skip bulk CopyIn
        // and read directly from GM in Compute.
        // Just allocate UB buffer for output staging.
        (void)offset;
        (void)curTileLength;
    }

    __aicore__ inline void Compute(int64_t offset, int64_t curTileLength) {
        // Allocate output staging buffer
        AscendC::LocalTensor<T> outLocal = outQueue.AllocTensor<T>();

        int64_t ndim = tilingData->ndim;

        for (int64_t i = 0; i < curTileLength; ++i) {
            int64_t globalIdx = offset + i;

            // Convert output linear index to multi-dimensional coordinates
            int64_t out_coords[MAX_DIM];
            int64_t tmp = globalIdx;
            for (int64_t d = ndim - 1; d >= 0; --d) {
                out_coords[d] = tmp % tilingData->out_shape[d];
                tmp /= tilingData->out_shape[d];
            }

            // Compute input coordinates: in_coords[dims[k]] = out_coords[k]
            int64_t in_coords[MAX_DIM];
            for (int64_t k = 0; k < ndim; ++k) {
                in_coords[tilingData->dims[k]] = out_coords[k];
            }

            // Compute input linear index
            int64_t srcIdx = 0;
            for (int64_t d = 0; d < ndim; ++d) {
                srcIdx += in_coords[d] * tilingData->in_strides[d];
            }

            // Copy element from input to output staging buffer
            outLocal.SetValue(i, inputGm.GetValue(srcIdx));
        }

        outQueue.EnQue<T>(outLocal);
    }

    __aicore__ inline void CopyOut(int64_t offset, int64_t curTileLength) {
        AscendC::LocalTensor<T> outLocal = outQueue.DeQue<T>();

        // Output is contiguous, use DataCopyPad for bulk transfer
        AscendC::DataCopyExtParams copyParams{
            1,
            static_cast<uint32_t>(curTileLength * sizeof(T)),
            0, 0, 0
        };
        AscendC::DataCopyPad(outputGm[offset], outLocal, copyParams);

        outQueue.FreeTensor(outLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECOUT, 1> outQueue;
    AscendC::GlobalTensor<T> inputGm;
    AscendC::GlobalTensor<T> outputGm;
    __gm__ PermuteTilingData* tilingData;
};

