    // Determine dtype from tiling data (we pass dtypeSize via a field)
    // For simplicity, we compile separate kernel instances
    // The host will launch the appropriate kernel based on dtype
}

// Kernel launch wrappers for different dtypes
extern "C" __global__ __aicore__ void permute_f32(GM_ADDR input, GM_ADDR output, GM_ADDR tiling) {
    KernelPermute<float> op;
    op.Init(input, output, tiling);
    op.Process();
}

