#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_permute.h"

#include <vector>
#include <numeric>

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;
constexpr int64_t MAX_DIM = 8;

struct PermuteTilingData {
    int64_t totalLength;
    int64_t usedCoreNum;
    int64_t formerNum;
    int64_t formerLength;
    int64_t tailNum;
    int64_t tailLength;
    int64_t tileLength;
    int64_t ndim;
    int64_t in_shape[MAX_DIM];
    int64_t out_shape[MAX_DIM];
    int64_t dims[MAX_DIM];
    int64_t in_strides[MAX_DIM];
};

namespace ascend_kernel {

static void ComputePermuteTiling(const std::vector<int64_t>& in_shape,
                                   const std::vector<int64_t>& dims,
                                   int64_t dtypeSize,
                                   PermuteTilingData& tiling) {
    // Compute total length
    tiling.totalLength = 1;
    for (auto dim : in_shape) {
        tiling.totalLength *= dim;
    }

    tiling.ndim = static_cast<int64_t>(in_shape.size());

    // Store input shape
    for (int64_t i = 0; i < tiling.ndim; ++i) {
        tiling.in_shape[i] = in_shape[i];
    }

    // Store output shape and dims
    for (int64_t i = 0; i < tiling.ndim; ++i) {
        tiling.out_shape[i] = in_shape[dims[i]];
        tiling.dims[i] = dims[i];
    }

    // Compute input strides (row-major)
    tiling.in_strides[tiling.ndim - 1] = 1;
    for (int64_t i = tiling.ndim - 2; i >= 0; --i) {
        tiling.in_strides[i] = tiling.in_strides[i + 1] * in_shape[i + 1];
    }

    // Get platform info
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // Block-level tiling
    int64_t totalLengthCore = (tiling.totalLength + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign = ((totalLengthCore * dtypeSize + CACHE_LINE_BYTE_LENGTH - 1) / CACHE_LINE_BYTE_LENGTH) *
                                    (CACHE_LINE_BYTE_LENGTH / dtypeSize);
    if (totalLengthCoreAlign == 0) {
        totalLengthCoreAlign = CACHE_LINE_BYTE_LENGTH / dtypeSize;
    }

    tiling.usedCoreNum = (tiling.totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    if (tiling.usedCoreNum > coreNum) {
        tiling.usedCoreNum = coreNum;
    }
    if (tiling.usedCoreNum <= 0) {
        tiling.usedCoreNum = 1;
    }

    tiling.formerNum = tiling.usedCoreNum - 1;
    tiling.tailNum = 1;
    tiling.formerLength = totalLengthCoreAlign;
    tiling.tailLength = tiling.totalLength - (tiling.usedCoreNum - 1) * tiling.formerLength;
    if (tiling.tailLength < 0) {
        tiling.tailLength = tiling.totalLength;
        tiling.formerNum = 0;
        tiling.tailNum = 1;
        tiling.formerLength = 0;
    }

    // UB-level tiling
    // For permute: single input, single output
    // bufferCoefficient = 4 (outQueue * 2, no inQueue needed since we read from GM directly)
    int64_t bufferCoefficient = 4;
    int64_t maxTileElements = static_cast<int64_t>(ubSize) / bufferCoefficient / dtypeSize;
    int64_t alignElements = 32 / dtypeSize;
    if (alignElements <= 0) {
        alignElements = 1;
    }
    tiling.tileLength = (maxTileElements / alignElements) * alignElements;
    if (tiling.tileLength <= 0) {
        tiling.tileLength = alignElements;
    }
}

at::Tensor permute(const at::Tensor& self, at::IntArrayRef dims) {
    // Validate input
    TORCH_CHECK(self.is_contiguous(), "permute: input tensor must be contiguous");

    int64_t ndim = self.dim();
    TORCH_CHECK(static_cast<int64_t>(dims.size()) == ndim,
                "permute: dims length must match input dimensions");

    // Compute output shape
    std::vector<int64_t> out_shape;
    for (int64_t i = 0; i < ndim; ++i) {
        out_shape.push_back(self.size(dims[i]));
    }

    // Create output tensor
    auto output = at::empty(out_shape, self.options());

    // Compute tiling
    int64_t dtypeSize = self.element_size();
    std::vector<int64_t> in_shape;
    for (int64_t i = 0; i < ndim; ++i) {
        in_shape.push_back(self.size(i));
    }
    std::vector<int64_t> dims_vec(dims.begin(), dims.end());

    PermuteTilingData tiling;
    ComputePermuteTiling(in_shape, dims_vec, dtypeSize, tiling);

    // Allocate workspace for tiling data on device
    auto workspace = at::empty({static_cast<int64_t>(sizeof(PermuteTilingData))},
                               at::TensorOptions().dtype(at::kByte).device(self.device()));
    // Copy tiling data to device
    auto tiling_cpu = at::from_blob(
        &tiling, {sizeof(PermuteTilingData)}, at::kByte).clone();
    workspace.copy_(tiling_cpu);

    int64_t blockDim = tiling.usedCoreNum;

    // Determine dtype parameter: 0=FP32, 1=FP16, 2=BF16
    int64_t dtype_param = 0;
    if (self.dtype() == at::kHalf) {
        dtype_param = 1;
    } else if (self.dtype() == at::kBFloat16) {
        dtype_param = 2;
    }

    // Launch kernel
    EXEC_KERNEL_CMD(permute, blockDim, self, output, workspace, dtype_param);

    return output;
}

} // namespace ascend_kernel
