#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;
constexpr int64_t MAX_DIM = 8;

struct PermuteTilingData {
    int64_t totalLength;
    int64_t usedCoreNum;
    int64_t formerNum;
    int64_t formerLength;
    int64_t tailNum;
    int64_t tailLength;
    int64_t tileLength;
    int64_t ndim;
    int64_t in_shape[MAX_DIM];
    int64_t out_shape[MAX_DIM];
    int64_t dims[MAX_DIM];
    int64_t in_strides[MAX_DIM];
};

template <typename T>
class KernelPermute {
public:
    __aicore__ inline KernelPermute() {}

    __aicore__ inline void Init(GM_ADDR input, GM_ADDR output, GM_ADDR tiling) {
        tilingData = reinterpret_cast<__gm__ PermuteTilingData*>(tiling);

        int64_t blockIdx = AscendC::GetBlockIdx();

        // inputGm points to the FULL input tensor (needed for arbitrary access)
        inputGm.SetGlobalBuffer((__gm__ T*)input, tilingData->totalLength);

        // outputGm points to this block's output region
        if (blockIdx < tilingData->formerNum) {
            this->blockLength = tilingData->formerLength;
            int64_t offset = tilingData->formerLength * blockIdx;
            outputGm.SetGlobalBuffer((__gm__ T*)output + offset, tilingData->formerLength);
            this->blockOffset = offset;
        } else {
            this->blockLength = tilingData->tailLength;
            int64_t tailIdx = blockIdx - tilingData->formerNum;
            int64_t offset = tilingData->formerLength * tilingData->formerNum + tilingData->tailLength * tailIdx;
            outputGm.SetGlobalBuffer((__gm__ T*)output + offset, tilingData->tailLength);
            this->blockOffset = offset;
        }

        pipe.InitBuffer(outQueue, BUFFER_NUM, tilingData->tileLength * sizeof(T));
    }

    __aicore__ inline void Process() {
        int64_t tileNum = (this->blockLength + tilingData->tileLength - 1) / tilingData->tileLength;
        int64_t tailTileLength = this->blockLength - (tileNum - 1) * tilingData->tileLength;

        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;

        for (int64_t i = 0; i < tileNum - 1; ++i) {
            Compute(i, tilingData->tileLength);
            CopyOut(i, tilingData->tileLength);
        }
        if (tileNum > 0) {
            Compute(tileNum - 1, alignedTailLen);
            CopyOut(tileNum - 1, alignedTailLen);
        }
    }

private:
    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength) {
        AscendC::LocalTensor<T> outLocal = outQueue.AllocTensor<T>();

        int64_t ndim = tilingData->ndim;
        int64_t tileOffset = this->blockOffset + progress * tilingData->tileLength;

        for (int64_t i = 0; i < curTileLength; ++i) {
            int64_t globalIdx = tileOffset + i;

            // Convert output linear index to multi-dimensional coordinates
            int64_t out_coords[MAX_DIM];
            int64_t tmp = globalIdx;
            for (int64_t d = ndim - 1; d >= 0; --d) {
                out_coords[d] = tmp % tilingData->out_shape[d];
                tmp /= tilingData->out_shape[d];
            }

            // Compute input coordinates: in_coords[dims[k]] = out_coords[k]
            int64_t in_coords[MAX_DIM];
            for (int64_t k = 0; k < ndim; ++k) {
                in_coords[tilingData->dims[k]] = out_coords[k];
            }

            // Compute input linear index
            int64_t srcIdx = 0;
            for (int64_t d = 0; d < ndim; ++d) {
                srcIdx += in_coords[d] * tilingData->in_strides[d];
            }

            // Copy element from input to output staging buffer
            // srcIdx is the global index in the input tensor
            outLocal.SetValue(i, inputGm.GetValue(srcIdx));
        }

        outQueue.EnQue<T>(outLocal);
    }

    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength) {
        AscendC::LocalTensor<T> outLocal = outQueue.DeQue<T>();

        AscendC::DataCopyExtParams copyParams{
            1,
            static_cast<uint32_t>(curTileLength * sizeof(T)),
            0, 0, 0
        };
        AscendC::DataCopyPad(outputGm[progress * tilingData->tileLength], outLocal, copyParams);

        outQueue.FreeTensor(outLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueue;
    AscendC::GlobalTensor<T> inputGm;
    AscendC::GlobalTensor<T> outputGm;
    __gm__ PermuteTilingData* tilingData;
    int64_t blockLength;
    int64_t blockOffset;
};

// Kernel entry with dtype support
// dtype: 0=FP32, 1=FP16, 2=BF16
extern "C" __global__ __aicore__ void permute(GM_ADDR input, GM_ADDR output, GM_ADDR tiling, int64_t dtype) {
    if (dtype == 1) {
        KernelPermute<half> op;
        op.Init(input, output, tiling);
        op.Process();
    } else if (dtype == 2) {
        KernelPermute<bfloat16_t> op;
        op.Init(input, output, tiling);
        op.Process();
    } else {
        KernelPermute<float> op;
        op.Init(input, output, tiling);
        op.Process();
    }
}
